CREATE ROLE authenticated; CREATE ROLE anon; CREATE SCHEMA auth; CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('test.actor',true),'')::uuid $$; CREATE FUNCTION public.current_user_can_process_payroll() RETURNS boolean LANGUAGE sql AS $$ SELECT coalesce(current_setting('test.allowed',true),'true')='true' $$;CREATE TABLE candidates(id uuid PRIMARY KEY); CREATE TABLE payroll_runs(id uuid PRIMARY KEY,unit_id uuid,period_start date,period_end date,status text,payroll_status text,payroll_processed_at timestamptz,payroll_processed_by uuid); CREATE TABLE attendance_sheets(id uuid PRIMARY KEY,unit_id uuid,period_start date,period_end date,status text,current_version integer,amendment_status text);CREATE TABLE deductions(id uuid DEFAULT gen_random_uuid() PRIMARY KEY,unit_id uuid,candidate_id uuid,deduction_type_id uuid,deduction_name text,deduction_date date,amount numeric CHECK(amount<9999),calculation_type text,entry_mode text,installments integer,description text,status text,source_kind text,source_ref text);CREATE TABLE additions(id uuid DEFAULT gen_random_uuid() PRIMARY KEY,candidate_id uuid,addition_type_id uuid,addition_name text,addition_date date,amount numeric,calculation_type text,entry_mode text,installments integer,description text,status text,source_kind text,source_ref text);CREATE TABLE employer_contributions(id uuid DEFAULT gen_random_uuid() PRIMARY KEY,candidate_id uuid,unit_id uuid,payroll_run_id uuid,contribution_name text,amount numeric,frequency text,period_start date,period_end date,contribution_date date,status text,notes text,source_kind text,source_ref text);CREATE TABLE payroll_processing_holds(id uuid DEFAULT gen_random_uuid() PRIMARY KEY,payroll_run_id uuid,candidate_id uuid,unit_id uuid,reason text,status text,created_by uuid);CREATE TABLE payroll_run_snapshots(id uuid DEFAULT gen_random_uuid() PRIMARY KEY,payroll_run_id uuid,unit_id uuid,candidate_id uuid,version integer,employee_code text,full_name text,paid_days numeric,ed_days numeric,gross numeric,total_deductions numeric,total_employer numeric,net_pay numeric,earnings jsonb,deductions jsonb,employer_contributions jsonb,additions jsonb,on_hold boolean,posted_by uuid,UNIQUE(payroll_run_id,candidate_id,version));GRANT ALL ON ALL TABLES IN SCHEMA public TO authenticated; GRANT USAGE ON SCHEMA auth TO authenticated;